using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Win32.SafeHandles;

namespace DSBridge.HotSwitch {
    // All values are generated by this service from the selected HID ancestry.
    // Pipe requests cannot supply a hub, port, serial or physical root.
    public sealed class UsbPortRecord {
        public string physical_id, physical_signature, hub_id, hub_signature, driver_key, serial, descriptor;
        public uint port;
    }
    internal sealed class UsbCycleResult {
        internal bool IoctlSucceeded;
        internal uint Win32Error, UsbStatus, Bytes, ReturnedPort, ExpectedPort;
        internal bool Success { get { return IoctlSucceeded && Win32Error == 0 && UsbStatus == 0 && Bytes == 8 && ReturnedPort == ExpectedPort; } }
    }
    internal interface IUsbPortOperations {
        UsbPortRecord Prepare(RecoveryRecord record);
        void Verify(RecoveryRecord record);
        UsbCycleResult Cycle(RecoveryRecord record);
        Node LoadInput(RecoveryRecord record);
        DeviceObservation ObserveInput(RecoveryRecord record);
    }
    internal static class UsbPortPolicy {
        internal const string HubClass = "{36fc9e60-c465-11cf-8056-444553540000}";
        internal static void ValidateFields(object value) {
            var fields = value as Dictionary<string, object>;
            if (fields == null || fields.Count != 8) throw new Rejected("invalid_journal", "Invalid USB port record.");
            foreach (string key in fields.Keys)
                if (key != "physical_id" && key != "physical_signature" && key != "hub_id" && key != "hub_signature" &&
                    key != "driver_key" && key != "serial" && key != "descriptor" && key != "port")
                    throw new Rejected("invalid_journal", "Unknown USB port field.");
        }
        static bool Same(string a, string b) { return String.Equals(a, b, StringComparison.OrdinalIgnoreCase); }
        static void Reject(string code, string text) { throw new Rejected(code, text); }
        internal static Node Physical(Node inputRoot) {
            Node physical = inputRoot == null ? null : inputRoot.Parent;
            if (physical == null || !Regex.IsMatch(inputRoot.Id, @"^USB\\VID_37D7&PID_2502&MI_00\\[^\\]+$", RegexOptions.IgnoreCase) ||
                !Regex.IsMatch(physical.Id, @"^USB\\VID_37D7&PID_2502\\[^\\\x00-\x20\x7f]{1,240}$", RegexOptions.IgnoreCase) ||
                !Same(physical.Service, "usbccgp") || !Same(physical.ClassGuid, HubClass))
                Reject("usb_not_supported", "Only the selected physical APEX USB composite controller can be cycled.");
            Node hub = physical.Parent;
            if (hub == null || !hub.Id.StartsWith("USB\\", StringComparison.OrdinalIgnoreCase) || !Same(hub.ClassGuid, HubClass) ||
                (!Same(hub.Service, "USBHUB3") && !Same(hub.Service, "usbhub")))
                Reject("usb_not_supported", "The controller must have a directly identifiable physical USB hub parent.");
            // Do not mistake a hub, controller or radio for the selected device.
            if (physical.Children.Count == 0 || physical.Children.Count > 8) Reject("usb_identity_changed", "The controller interface list is invalid.");
            bool selected = false; var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (Node child in physical.Children) {
                if (!ids.Add(child.Id) || !Regex.IsMatch(child.Id, @"^USB\\VID_37D7&PID_2502&MI_0[0-3]\\[^\\]+$", RegexOptions.IgnoreCase))
                    Reject("usb_identity_changed", "The physical device contains an unrecognized interface.");
                if (Same(child.Id, inputRoot.Id)) selected = true;
            }
            if (!selected) Reject("usb_identity_changed", "The selected input is not an interface of this controller.");
            return physical;
        }
        internal static void ValidateRecord(RecoveryRecord record) {
            UsbPortRecord port = record.usb;
            if (port == null || !record.root_id.StartsWith("USB\\VID_37D7&PID_2502&MI_00\\", StringComparison.OrdinalIgnoreCase) ||
                !Regex.IsMatch(port.physical_id ?? "", @"^USB\\VID_37D7&PID_2502\\[^\\\x00-\x20\x7f]{1,240}$", RegexOptions.IgnoreCase) ||
                String.IsNullOrEmpty(port.hub_id) || !port.hub_id.StartsWith("USB\\", StringComparison.OrdinalIgnoreCase) || port.hub_id.Length > 512 ||
                !Regex.IsMatch(port.physical_signature ?? "", "^[0-9a-f]{64}$") || !Regex.IsMatch(port.hub_signature ?? "", "^[0-9a-f]{64}$") ||
                !Regex.IsMatch(port.driver_key ?? "", @"^\{[0-9a-f-]{36}\}\\[0-9]{4,8}$", RegexOptions.IgnoreCase) ||
                String.IsNullOrEmpty(port.serial) || port.serial.Length > 126 || port.serial.IndexOfAny(new char[] {'\\', '\0', '\r', '\n'}) >= 0 ||
                !Regex.IsMatch(port.descriptor ?? "", "^[0-9A-F]{36}$") || port.port < 1 || port.port > 255)
                Reject("invalid_journal", "The USB recovery identity is invalid.");
            byte[] descriptor = new byte[18];
            for (int i = 0; i < descriptor.Length; i++) descriptor[i] = Convert.ToByte(port.descriptor.Substring(i * 2, 2), 16);
            ValidateDescriptor(descriptor);
        }
        internal static void ValidateDescriptor(byte[] d) {
            if (d == null || d.Length != 18 || d[0] != 18 || d[1] != 1 || d[4] == 9 ||
                BitConverter.ToUInt16(d, 8) != 0x37D7 || BitConverter.ToUInt16(d, 10) != 0x2502 || d[16] == 0)
                Reject("usb_identity_changed", "The port does not contain the selected non-hub APEX controller with a serial descriptor.");
        }
        internal static void Match(UsbPortRecord expected, UsbPortRecord actual) {
            if (!Same(expected.physical_id, actual.physical_id) || expected.physical_signature != actual.physical_signature ||
                !Same(expected.hub_id, actual.hub_id) || expected.hub_signature != actual.hub_signature || expected.port != actual.port ||
                !Same(expected.driver_key, actual.driver_key) || !String.Equals(expected.serial, actual.serial, StringComparison.Ordinal) || expected.descriptor != actual.descriptor)
                Reject("usb_identity_changed", "The selected USB controller, hub or port identity changed.");
        }
    }
    internal sealed class UsbPortOperations : IUsbPortOperations {
        // Windows SDK usbiodef.h / usbioctl.h; FILE_DEVICE_USB=0x22,
        // METHOD_BUFFERED=0, FILE_ANY_ACCESS=0. No hub-reset IOCTL exists here.
        internal const uint NodeInformation = 0x220408, ConnectionInformation = 0x220448,
            DescriptorRequest = 0x220410, DriverKeyName = 0x220420, CyclePort = 0x220444;
        internal static readonly Guid HubInterface = new Guid("f18a0e88-c30c-11d0-8815-00a0c906bed8");
        [DllImport("cfgmgr32.dll", CharSet = CharSet.Unicode)] static extern uint CM_Get_Device_Interface_List_SizeW(out uint length, ref Guid guid, string device, uint flags);
        [DllImport("cfgmgr32.dll", CharSet = CharSet.Unicode)] static extern uint CM_Get_Device_Interface_ListW(ref Guid guid, string device, char[] buffer, uint length, uint flags);
        [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern SafeFileHandle CreateFileW(string path, uint access, uint share, IntPtr security, uint creation, uint flags, IntPtr template);
        [DllImport("kernel32.dll", SetLastError = true)] static extern bool DeviceIoControl(SafeFileHandle handle, uint code, [In] byte[] input, uint inputLength, [In, Out] byte[] output, uint outputLength, out uint returned, IntPtr overlapped);
        internal static void Put32(byte[] b, int offset, uint value) { Buffer.BlockCopy(BitConverter.GetBytes(value), 0, b, offset, 4); }
        static void Put16(byte[] b, int offset, ushort value) { Buffer.BlockCopy(BitConverter.GetBytes(value), 0, b, offset, 2); }
        static uint Query(SafeFileHandle handle, uint code, byte[] buffer, uint minimum) {
            uint bytes;
            if (!DeviceIoControl(handle, code, buffer, (uint)buffer.Length, buffer, (uint)buffer.Length, out bytes, IntPtr.Zero))
                throw new Rejected("usb_query_failed", "USB port identity query failed (" + Marshal.GetLastWin32Error() + ").");
            if (bytes < minimum || bytes > buffer.Length) throw new Rejected("usb_query_failed", "USB query returned an incomplete structure.");
            return bytes;
        }
        static SafeFileHandle OpenHub(string id) {
            Guid guid = HubInterface; uint length;
            if (CM_Get_Device_Interface_List_SizeW(out length, ref guid, id, 0) != 0 || length < 3 || length > 8192)
                throw new Rejected("usb_query_failed", "The exact parent hub interface is unavailable.");
            var buffer = new char[length];
            if (CM_Get_Device_Interface_ListW(ref guid, id, buffer, length, 0) != 0)
                throw new Rejected("usb_query_failed", "The exact parent hub interface changed.");
            string[] interfaces = new string(buffer).Split(new char[] {'\0'}, StringSplitOptions.RemoveEmptyEntries);
            if (interfaces.Length != 1 || !interfaces[0].StartsWith(@"\\?\", StringComparison.Ordinal) ||
                !interfaces[0].EndsWith("#{" + HubInterface.ToString() + "}", StringComparison.OrdinalIgnoreCase))
                throw new Rejected("usb_port_ambiguous", "The parent hub does not have exactly one verified interface.");
            SafeFileHandle handle = CreateFileW(interfaces[0], 0xC0000000, 3, IntPtr.Zero, 3, 0, IntPtr.Zero);
            if (handle.IsInvalid) { int error = Marshal.GetLastWin32Error(); handle.Dispose(); throw new Win32Exception(error, "Cannot open the verified parent USB hub."); }
            return handle;
        }
        internal static byte[] Connection(SafeFileHandle handle, uint port, uint selectedPort) {
            // Packed SDK header is 35 bytes plus up to 30 USB_PIPE_INFO entries.
            byte[] info = new byte[2048]; Put32(info, 0, port);
            uint returned = Query(handle, ConnectionInformation, info, 35);
            ValidateConnectionIndex(info, returned, port, selectedPort);
            return info;
        }
        internal static void ValidateConnectionIndex(byte[] info, uint returned, uint port, uint selectedPort) {
            if (info.Length < 35 || returned < 35 || returned > info.Length) throw new Rejected("usb_query_failed", "USB connection header is incomplete.");
            if (BitConverter.ToUInt32(info, 0) != port) throw new Rejected("usb_query_failed", "USB connection query returned another index: requested=" +
                port + ", selected=" + selectedPort + ", returned_index=" + BitConverter.ToUInt32(info, 0) +
                ", connection_status=" + BitConverter.ToUInt32(info, 31) + ", returned_bytes=" + returned + ".");
        }
        internal static byte[] DeviceDescriptor(byte[] connection) {
            if (connection.Length < 35 || BitConverter.ToUInt32(connection, 31) != 1 || connection[24] != 0)
                throw new Rejected("usb_identity_changed", "The selected port is disconnected or contains a hub.");
            byte[] descriptor = new byte[18]; Buffer.BlockCopy(connection, 4, descriptor, 0, 18);
            UsbPortPolicy.ValidateDescriptor(descriptor); return descriptor;
        }
        static string DriverKey(SafeFileHandle handle, uint port) {
            byte[] probe = new byte[10]; Put32(probe, 0, port); Query(handle, DriverKeyName, probe, 8);
            uint length = BitConverter.ToUInt32(probe, 4);
            if (length < 12 || length > 8192 || length % 2 != 0) throw new Rejected("usb_query_failed", "USB driver key length is invalid.");
            byte[] data = new byte[length]; Put32(data, 0, port);
            uint returned = Query(handle, DriverKeyName, data, length);
            return ParseDriverKey(data, returned, port);
        }
        internal static string ParseDriverKey(byte[] data, uint returned, uint port) {
            if (returned < 10 || returned > data.Length || returned % 2 != 0 || BitConverter.ToUInt32(data, 0) != port || BitConverter.ToUInt32(data, 4) != returned)
                throw new Rejected("usb_query_failed", "USB driver key identity query changed.");
            string value = Encoding.Unicode.GetString(data, 8, (int)returned - 8);
            int end = value.IndexOf('\0');
            // SDK ActualLength can include the trailing WCHAR in the variable
            // structure as well as the string terminator. Accept zero padding,
            // but never hidden nonzero characters after the first terminator.
            if (end < 1)
                throw new Rejected("usb_query_failed", "USB driver key string is malformed.");
            for (int i = end; i < value.Length; i++) if (value[i] != '\0')
                throw new Rejected("usb_query_failed", "USB driver key contains data after its terminator.");
            return value.Substring(0, end);
        }
        static byte[] StringDescriptor(SafeFileHandle handle, uint port, byte index, ushort language) {
            byte[] request = new byte[267]; Put32(request, 0, port);
            request[4] = 0x80; request[5] = 6; Put16(request, 6, (ushort)(0x0300 | index)); Put16(request, 8, language); Put16(request, 10, 255);
            uint size = Query(handle, DescriptorRequest, request, 14);
            int count = request[12];
            if (BitConverter.ToUInt32(request, 0) != port || request[13] != 3 || count < 4 || count % 2 != 0 || size != count + 12)
                throw new Rejected("usb_serial_unavailable", "USB string descriptor is malformed or incomplete.");
            byte[] value = new byte[count]; Buffer.BlockCopy(request, 12, value, 0, count); return value;
        }
        static string Serial(SafeFileHandle handle, uint port, byte index) {
            if (index == 0) throw new Rejected("usb_serial_unavailable", "A USB serial descriptor is required for an automatic port cycle.");
            byte[] languages = StringDescriptor(handle, port, 0, 0);
            ushort language = BitConverter.ToUInt16(languages, 2);
            if (language == 0) throw new Rejected("usb_serial_unavailable", "USB serial language is invalid.");
            byte[] serial = StringDescriptor(handle, port, index, language);
            string text = new UnicodeEncoding(false, false, true).GetString(serial, 2, serial.Length - 2);
            if (text.Length == 0 || text.IndexOf('\0') >= 0) throw new Rejected("usb_serial_unavailable", "USB serial is empty or invalid.");
            return text;
        }
        static uint Ports(SafeFileHandle handle) {
            byte[] node = new byte[76]; // USB_NODE_INFORMATION: node type + packed hub information.
            Query(handle, NodeInformation, node, 7);
            if (BitConverter.ToUInt32(node, 0) != 0 || node[6] == 0)
                throw new Rejected("usb_query_failed", "USB hub port count is unavailable.");
            return node[6];
        }
        static UsbPortRecord Pnp(RecoveryRecord record) {
            Node leaf = Devices.LoadUsbInput(record), root = Policy.Select(leaf);
            Identity.VerifyUsbRoot(record, root);
            Node physical = UsbPortPolicy.Physical(root);
            uint port = Devices.DwordProperty(physical.Id, 0x1d); // CM_DRP_ADDRESS, not SPDRP_ADDRESS.
            string driver = Devices.TextProperty(physical.Id, 0x0a); // CM_DRP_DRIVER.
            if (port == 0 || port > 255) throw new Rejected("usb_query_failed", "The controller has no unambiguous USB port address.");
            return new UsbPortRecord {physical_id = physical.Id, physical_signature = Identity.Ancestors(physical),
                hub_id = physical.Parent.Id, hub_signature = Identity.Ancestors(physical.Parent), port = port, driver_key = driver};
        }
        internal static UsbPortRecord BindSelected(UsbPortRecord pnp, uint count, Func<uint, byte[]> connection,
            Func<uint, string> driverKey, Func<uint, byte, string> serial) {
            if (pnp.port > count) throw new Rejected("usb_port_ambiguous", "USB address exceeds the verified parent hub port count.");
            byte[] info = connection(pnp.port);
            ValidateConnectionIndex(info, (uint)info.Length, pnp.port, pnp.port);
            byte[] descriptor = DeviceDescriptor(info);
            string key = driverKey(pnp.port);
            if (!String.Equals(key, pnp.driver_key, StringComparison.OrdinalIgnoreCase))
                throw new Rejected("usb_identity_changed", "The selected USB port driver key belongs to another device.");
            pnp.serial = serial(pnp.port, descriptor[16]);
            pnp.descriptor = BitConverter.ToString(descriptor).Replace("-", "");
            // PnP instance IDs need not equal the raw iSerialNumber string.
            // Driver key + physical ancestry + port binds both independent
            // identities. Retain and compare both without text normalization.
            // The selected port's driver key is the device-instance-specific
            // PnP key, not a generic driver name. Together with exact parent hub
            // and CM_DRP_ADDRESS it identifies one physical port. Never query
            // unrelated ports, whose disconnected headers may be zeroed.
            return pnp;
        }
        static UsbPortRecord Bind(RecoveryRecord record, SafeFileHandle handle, UsbPortRecord pnp) {
            BindSelected(pnp, Ports(handle), delegate(uint port) {return Connection(handle, port, pnp.port);},
                delegate(uint port) {return DriverKey(handle, port);}, delegate(uint port, byte index) {return Serial(handle, port, index);});
            // Re-sample PnP after USB queries. Never silently use a moved port.
            UsbPortRecord fresh = Pnp(record); fresh.serial = pnp.serial; fresh.descriptor = pnp.descriptor;
            UsbPortPolicy.Match(pnp, fresh); return pnp;
        }
        public UsbPortRecord Prepare(RecoveryRecord record) {
            UsbPortRecord pnp = Pnp(record);
            using (SafeFileHandle hub = OpenHub(pnp.hub_id)) return Bind(record, hub, pnp);
        }
        public void Verify(RecoveryRecord record) {
            Identity.ValidateRecord(record); UsbPortRecord pnp = Pnp(record);
            using (SafeFileHandle hub = OpenHub(pnp.hub_id)) UsbPortPolicy.Match(record.usb, Bind(record, hub, pnp));
        }
        public Node LoadInput(RecoveryRecord record) { return Devices.LoadUsbInput(record); }
        public DeviceObservation ObserveInput(RecoveryRecord record) {
            Node leaf = LoadInput(record); Node root = Policy.Select(leaf);
            Identity.VerifyUsbRoot(record, root);
            DeviceObservation input = Devices.ObserveExact(leaf.Id);
            if (!input.Healthy) return input;
            DeviceObservation parent = Devices.ObserveExact(leaf.Parent.Id);
            return parent.Healthy ? input : parent;
        }
        public UsbCycleResult Cycle(RecoveryRecord record) {
            Identity.ValidateRecord(record); UsbPortRecord pnp = Pnp(record);
            using (SafeFileHandle hub = OpenHub(pnp.hub_id)) {
                UsbPortPolicy.Match(record.usb, Bind(record, hub, pnp));
                // The sole mutating USB call. The handle is the exact parent
                // hub and the request selects only the validated device port.
                byte[] parameters = new byte[8]; Put32(parameters, 0, record.usb.port); Put32(parameters, 4, UInt32.MaxValue);
                uint returned;
                bool success = DeviceIoControl(hub, CyclePort, parameters, 8, parameters, 8, out returned, IntPtr.Zero);
                uint error = success ? 0 : (uint)Marshal.GetLastWin32Error();
                return new UsbCycleResult {IoctlSucceeded = success, Win32Error = error, Bytes = returned,
                    UsbStatus = BitConverter.ToUInt32(parameters, 4), ReturnedPort = BitConverter.ToUInt32(parameters, 0), ExpectedPort = record.usb.port};
            }
        }
    }
}
